import 'package:accounting_software/app/core/localization/translations/app_key.dart';
import 'package:flutter/material.dart';
import 'package:flutter_bloc/flutter_bloc.dart';
import 'package:accounting_software/app/core/presentation/widgets/crud_editor/crud_editor.dart';
import 'package:accounting_software/app/core/presentation/widgets/app_text_field/app_text_field.dart';
import 'package:accounting_software/app/core/presentation/widgets/app_text/app_text.dart';
import 'package:accounting_software/app/features/catalog/fabric_types/domain/entity/fabric_type.dart';
import 'package:accounting_software/app/features/catalog/fabric_types/domain/entity/fabric_type_draft.dart';
import 'package:accounting_software/app/features/catalog/fabric_types/presentation/cubit/fabric_types_form/fabric_type_form_cubit.dart';
import 'package:accounting_software/app/features/catalog/fabric_types/presentation/localization/fabric_types_keys.dart';
class FabricTypeEditorDialog extends StatefulWidget{const FabricTypeEditorDialog({super.key,this.item});final CatalogFabricType? item;@override State<FabricTypeEditorDialog> createState()=>_FabricTypeEditorDialogState();}
class _FabricTypeEditorDialogState extends State<FabricTypeEditorDialog>{
 late final CrudEditorFields fields;bool active=true;bool named=false;FabricCategory? selected;
 TextEditingController get name=>fields['name'];TextEditingController get code=>fields['code'];TextEditingController get description=>fields['description'];
 @override void initState(){super.initState();final e=widget.item;active=e?.isActive??true;selected=e?.fabricCategory;named=e?.isNamedFabric??false;fields=CrudEditorFields(initialValues:{'name':e?.name??'','code':e?.code??'','description':e?.description??''});}
 @override void dispose(){fields.dispose();super.dispose();}
 Future<void> save()=>context.read<FabricTypeFormCubit>().save(id:widget.item?.id,draft:FabricTypeDraft(name:name.text.trim(),code:code.text.trim(),description:description.text.trim().isEmpty?null:description.text.trim(),isActive:active,fabricCategory:selected,isNamedFabric:named));
 @override Widget build(BuildContext context)=>CrudEditorDialog<FabricTypeFormCubit,FabricTypeFormStatus,FabricTypeFormEffect>(cubit:context.read<FabricTypeFormCubit>(),fields:fields,mode:widget.item==null?CrudEditorMode.add:CrudEditorMode.edit,labels:const CrudEditorLabels(addTitle:FabricTypesKeys.add,editTitle:FabricTypesKeys.edit,subtitle:FabricTypesKeys.description,save:FabricTypesKeys.save,cancel:FabricTypesKeys.cancel),isSaving:(s)=>s==FabricTypeFormStatus.saving,outcome:(e)=>switch(e){FabricTypeSavedEffect()=>const CrudEditorSuccess(),FabricTypeSaveFailedEffect(:final messageKey)=>CrudEditorFailure(messageKey)},onSave:save,builder:(context,scope)=>Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[AppTextField(controller:name,labelKey:FabricTypesKeys.name,validator:(v)=>v==null||v.trim().isEmpty?FabricTypesKeys.required.tr(context:context):null,onChanged:(_)=>scope.clearFailure()),AppTextField(controller:code,labelKey:FabricTypesKeys.code,validator:(v)=>v==null||v.trim().isEmpty?FabricTypesKeys.required.tr(context:context):null,onChanged:(_)=>scope.clearFailure()),DropdownButtonFormField<FabricCategory>(value:selected,decoration:InputDecoration(labelText:FabricTypesKeys.category.tr(context:context)),items:[for(final v in FabricCategory.values)DropdownMenuItem(value:v,child:Text(switch(v){FabricCategory.knit=>FabricTypesKeys.knit.tr(context:context),FabricCategory.woven=>FabricTypesKeys.woven.tr(context:context),FabricCategory.fleece=>FabricTypesKeys.fleece.tr(context:context)}))],onChanged:(v)=>setState(()=>selected=v)),AppTextField(controller:description,labelKey:FabricTypesKeys.description,maxLines:3),SwitchListTile(value:active,title:AppText(active?FabricTypesKeys.active:FabricTypesKeys.inactive),onChanged:(v)=>setState(()=>active=v)),SwitchListTile(value:named,title:AppText(FabricTypesKeys.named),onChanged:(v)=>setState(()=>named=v))]));}
}